-- ============================================================
-- SplitSure – Migration 015: password-reset e-mails sent by SplitSure
--
-- The reset code is generated by Supabase Auth (admin generateLink) and e-mailed
-- by the `agreement-emails` Edge Function through the project's own sender, with
-- the branded template (instead of Supabase's default mailer, which lands in spam
-- and has no logo). This table only throttles requests per address.
-- Safe to re-run.
-- ============================================================

create table if not exists public.auth_email_throttle (
  key     text primary key,          -- e.g. 'reset:someone@example.com'
  sent_at timestamptz not null default now()
);
alter table public.auth_email_throttle enable row level security;
-- No policies: only the service role (Edge Function) reads or writes this table.
